Self-Service Web App.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

System_Ext(api_gateway, "API Gateway", "Nginx/Kong")
System_Ext(payment_gateway, "Payment Gateway", "External payment provider")

Container_Boundary(self_service_web_app, "Self-Service Web App") {
    Component(bff_routing_and_session_handler, "BFF Routing & Session Handler", "Next.js API Routes / Node.js", "Handles client-side routing, renders UI pages, and translates HttpOnly cookies to JWT tokens for backend API communication.")
    Component(catalogue_search_ui, "Catalogue Search UI", "React Component / Client-side Cache", "Provides rapid catalogue search interactions and caches search results in the browser.")
    Component(fine_payment_widget, "Fine Payment Widget", "React Component / Iframe Integration", "Manages fine settlements securely via an isolated iframe tokenization mechanism.")
}

Rel(bff_routing_and_session_handler, api_gateway, "HTTPS/REST with HttpOnly Cookie-to-JWT translation", "HTTPS")
Rel(fine_payment_widget, payment_gateway, "HTTPS, via isolated iframe tokenization", "HTTPS")

@enduml

Admin/Staff Portal.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(admin_staff_portal, "Admin/Staff Portal") {
    Component(Staff_Authentication_Controller, "Staff Authentication Controller", "React Router / OIDC Client", "Manages staff authentication flows, token exchange, and secure session state within the Admin/Staff Portal.")
    Component(Admin_Dashboard_UI, "Admin Dashboard UI", "React Admin / Material-UI", "High-density data grids and administrative workflows for managing library operations and cataloguing.")
    Component(Staff_API_Client, "Staff API Client", "Axios / Fetch API", "Handles secure HTTP/REST communication with JWT authentication headers targeting the API Gateway.")
}

Rel(Staff_Authentication_Controller, Staff_API_Client, "Supplies JWT for authorized requests", "")
Rel(Admin_Dashboard_UI, Staff_API_Client, "Initiates data queries and administrative mutations", "")
@enduml
